 "Ζαοζέρσκ, απόγονος του αγίου πρίγκιπος Θεοδώρου του Σμολένσκ και του "
 "Γιαροσλάβλ. Ανατραφείς εν βαθεία ευσεβεία, εις ηλικίαν είκοσι ετών "
 "εγκατέλειψε την πριγκιπικήν κληρονομίαν του και έλαβε την κουράν με το "
