 "τηρουμένων τον Αύγουστον. Ότε ο Κύριος εκήρυττεν εν τη Γαλιλαία, ο "
 "Αύγαρος, ο τοπάρχης της Εδέσσης, έκειτο ασθενής υπό λέπρας, και ακούσας "
 "περί των πολλών θαυμάτων του Χριστού απέστειλεν αγγελιαφόρον να Τον "
