 "εν τω διωγμώ επί του αυτοκράτορος Αυρηλιανού, περί το έτος 274. Τα "
 "ελληνικά συναξάρια αναγράφουν τον τρόπον της αθλήσεως αυτού: αρνηθείς να "
 "απαρνηθή τον Χριστόν, εθανατώθη δια πίσσης κοχλαζούσης καταχυθείσης επί το "
