 "πιστούς συναχθήναι εν ευφροσύνη, επειδή μέλλει η Μήτηρ του Θεού εκδημήσαι "
 "εκ της γης εις την επουράνιον βασιλείαν, αναληφθήναι εν δόξη υπό του Υιού "
