 "τον μαθητήν του Αθανάσιον εις το Σερπούχωφ· και εκεί ο Νίκων εκάρη και "
 "εχειροτονήθη, επιστρέψας τέλος προς τον Σέργιον, ο οποίος τοσούτον τον "
