 "και ιδρύσας εν Μπριάνσκ μονήν εις τιμήν των αποστόλων Πέτρου και Παύλου, "
 "έπραξεν ό ολίγοι άρχοντες έπραξαν: απέθετο τον ηγεμονικόν του βαθμόν εξ "
