 "γράμματά του και χαρίσας το μερίδιόν του, απεσύρθη εις την έρημον επί του "
 "ποταμού Ντεμιάνκα μεταξύ Πσκώβ και Πόρχωφ, όπου μετά καιρόν έλαβε το "
